128	func TestMultiDependencyPendingListAndSlotReason(t *testing.T) {
129		s, _ := openTestStore(t)
130		started, block, release, _, _ := gateCompute(t, s)
131		block(1)
132	
133		head := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1}})
134		waitStarted(t, started, head.ID)
135		u1 := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{2}})
136		u2 := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{3}})
137		down := mustSubmit(t, s, SubmitRequest{
138			Submitter: "a", Values: []int64{4},
139			Dependencies: []uint64{u1.ID, u2.ID},
140		})
141		later := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{5}})
142	
143		d, _ := s.Get(down.ID)
144		if d.WaitReason != WaitDependency {
145			t.Fatalf("reason=%q want WaitDependency", d.WaitReason)
146		}
147		if len(d.PendingDependencies) != 2 || d.PendingDependencies[0] != u1.ID || d.PendingDependencies[1] != u2.ID {
148			t.Fatalf("pending=%v want [%d %d] in submit order", d.PendingDependencies, u1.ID, u2.ID)
149		}
150		// 等待多上游的作业不挡后面的可运行作业。
151		l, _ := s.Get(later.ID)
152		if l.WaitReason != WaitSlot {
153			t.Fatalf("later job reason=%q want WaitSlot", l.WaitReason)
154		}
155	
156		// 堵住 u2：u1 成功后 down 仍排队，待列出项应只剩 u2。
157		block(u2.ID)
158		release(head.ID)
159		waitStatus(t, s, head.ID, StatusSucceeded)
160		waitStatus(t, s, u1.ID, StatusSucceeded)
161		d, _ = s.Get(down.ID)
162		if d.WaitReason != WaitDependency || len(d.PendingDependencies) != 1 || d.PendingDependencies[0] != u2.ID {
163			t.Fatalf("after u1: reason=%q pending=%v, want WaitDependency/[%d]", d.WaitReason, d.PendingDependencies, u2.ID)
164		}
165		// u2 也成功后，依赖全部就绪：排队原因变为等待计算位置（作业也可能已开始运行）。
166		release(u2.ID)
167		waitStatus(t, s, u2.ID, StatusSucceeded)
168		d, _ = s.Get(down.ID)
169		if d.Status == StatusQueued {
170			if d.WaitReason != WaitSlot || len(d.PendingDependencies) != 0 {
171				t.Fatalf("after all upstreams: reason=%q pending=%v, want WaitSlot/empty", d.WaitReason, d.PendingDependencies)
172			}
173		} else if d.Status != StatusRunning && d.Status != StatusSucceeded {
174			t.Fatalf("after all upstreams: status=%s reason=%q", d.Status, d.WaitReason)
175		}
176		waitStatus(t, s, later.ID, StatusSucceeded)
177		waitStatus(t, s, down.ID, StatusSucceeded)
178	}
