250	func TestMultiDependencyIdempotencyContentAndOrder(t *testing.T) {
251		s, _ := openTestStore(t)
252		u1 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "u1", Values: []int64{1}})
253		u2 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "u2", Values: []int64{2}})
254		waitStatus(t, s, u1.ID, StatusSucceeded)
255		waitStatus(t, s, u2.ID, StatusSucceeded)
256	
257		orig := mustSubmit(t, s, SubmitRequest{
258			Submitter: "a", RequestID: "k", Values: []int64{1}, Seed: 0,
259			Dependencies: []uint64{u1.ID, u2.ID},
260		})
261		// 单依赖方式与只含同一作业号的列表视为相同内容：
262		// 先以单依赖方式提交，再以列表 [同一作业号] 重放 → 同一作业。
263		single := mustSubmit(t, s, SubmitRequest{
264			Submitter: "a", RequestID: "ks", Values: []int64{1}, Seed: 0,
265			HasDependency: true, DependencyID: u1.ID,
266		})
267		singleReplay := mustSubmit(t, s, SubmitRequest{
268			Submitter: "a", RequestID: "ks", Values: []int64{1}, Seed: 0,
269			Dependencies: []uint64{u1.ID},
270		})
271		if singleReplay.ID != single.ID {
272			t.Fatalf("single-dep vs list[same] must be identical content: %d vs %d", singleReplay.ID, single.ID)
273		}
274		// 次序变化 → 冲突。
275		if _, err := s.Submit(SubmitRequest{
276			Submitter: "a", RequestID: "k", Values: []int64{1}, Seed: 0,
277			Dependencies: []uint64{u2.ID, u1.ID},
278		}); !errors.Is(err, ErrIdempotencyConflict) {
279			t.Fatal("order change must conflict")
280		}
281		// 内容变化 → 冲突。
282		if _, err := s.Submit(SubmitRequest{
283			Submitter: "a", RequestID: "k", Values: []int64{1}, Seed: 0,
284			Dependencies: []uint64{u1.ID},
285		}); !errors.Is(err, ErrIdempotencyConflict) {
286			t.Fatal("list change must conflict")
287		}
288		// 完全相同 → 原作业。
289		same := mustSubmit(t, s, SubmitRequest{
290			Submitter: "a", RequestID: "k", Values: []int64{1}, Seed: 0,
291			Dependencies: []uint64{u1.ID, u2.ID},
292		})
293		if same.ID != orig.ID {
294			t.Fatalf("same content replayed id=%d want %d", same.ID, orig.ID)
295		}
296		// 原记录内容不变。
297		g, _ := s.Get(orig.ID)
298		if len(g.Dependencies) != 2 || g.Dependencies[0] != u1.ID || g.Dependencies[1] != u2.ID {
299			t.Fatalf("original record altered: %v", g.Dependencies)
300		}
301	}
