		t.Fatal(err)
	}
	defer s2.Close()
	got, _ := s2.Get(j.ID)
	if got.Status != StatusFailed || got.Archive != nil {
		t.Fatalf("persisted status=%s archive=%v", got.Status, got.Archive)
	}
}

