59			t.Fatal(err)
60		}
61		if g.Status != StatusFailed {
62			t.Fatalf("job %d must fail closed, got %s", id, g.Status)
63		}
64		if g.Archive != nil || g.EffectiveValues != nil {
65			t.Fatalf("job %d must not carry archive/effective inputs: archive=%v effective=%v",
66				id, g.Archive, g.EffectiveValues)
67		}
68		if g.ID != id {
69			t.Fatalf("original job id changed: got %d, want %d", g.ID, id)
70		}
71		if len(g.Values) != len(wantValues) {
72			t.Fatalf("original values changed: %v, want %v", g.Values, wantValues)
73		}
74		for i := range wantValues {
75			if g.Values[i] != wantValues[i] {
76				t.Fatalf("original values changed: %v, want %v", g.Values, wantValues)
77			}
78		}
79		if !strings.Contains(g.FailureReason, "实际输入与原始参数或依赖数量不符") ||
80			!strings.Contains(g.FailureReason, "成功结果不可用") {
81			t.Fatalf("job %d reason=%q must state effective inputs mismatch and success results unusable",
82				id, g.FailureReason)
83		}
84	}
85	
86	// 原始参数 [2,-3] 的实际输入被换成另一份序列 [-3,2]：总和与平方和不变，
87	// 摘要、日志与校验值也按这份实际输入保持自洽，重开后仍必须判定失败。
88	func TestReopenRejectsSwappedEffectiveInputs(t *testing.T) {
89		dir := t.TempDir()
90		s, err := Open(dir)
91		if err != nil {
92			t.Fatal(err)
93		}
94		j := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{2, -3}})
95		done := waitStatus(t, s, j.ID, StatusSucceeded)
96		if done.Archive.Sum != -1 || done.Archive.SumOfSquares != 13 {
97			t.Fatalf("real result=%d,%d", done.Archive.Sum, done.Archive.SumOfSquares)
98		}
99		if err := s.Close(); err != nil {
100			t.Fatal(err)
101		}
102	
103		// 换序：[-3,2] 与 [2,-3] 的总和、平方和完全相同。
104		rewriteRecordEffectiveInputs(t, dir, j.ID, []int64{-3, 2})
105	
106		s2, err := Open(dir)
107		if err != nil {
108			t.Fatal(err)
109		}
110		defer s2.Close()
111		assertCorrespondenceFailure(t, s2, j.ID, []int64{2, -3})
112	
113		data, err := os.ReadFile(filepath.Join(dir, jobFileName(j.ID)))
114		if err != nil {
115			t.Fatal(err)
116		}
117		if !strings.Contains(string(data), `"status": "failed"`) {
118			t.Fatal("on-disk record must be rewritten as failed")
119		}
120	}
121	
122	// 原始部分被替换、截短或多出未记录输入时，即使全套摘要自洽也必须失败；
123	// 负数、零与重复整数按位置判断，不能只比较总和或忽略次序。
124	func TestReopenRejectsMismatchedEffectiveInputs(t *testing.T) {
125		cases := []struct {
126			name   string
127			values []int64
128			eff    []int64
129		}{
130			// 次序调换、含负数与重复值：[0,-2,-2,3] 与 [0,-2,3,-2] 总和相同。
131			{"reordered with negatives zero and dups",
132				[]int64{0, -2, -2, 3}, []int64{0, -2, 3, -2}},
133			// 同长度但替换为另一份序列。
134			{"replaced same length", []int64{2, -3}, []int64{1, -2}},
135			// 无依赖却多出一个未记录的输入。
136			{"extra unrecorded input", []int64{2, -3}, []int64{2, -3, 99}},
137			// 无依赖却截短原始序列。
138			{"truncated original", []int64{2, -3}, []int64{2}},
139			// 原始序列开头被塞入一个值，原始参数整体后移。
140			{"prepended value", []int64{2, -3}, []int64{99, 2, -3}},
141		}
142		for _, tc := range cases {
143			t.Run(tc.name, func(t *testing.T) {
144				dir := t.TempDir()
145				s, err := Open(dir)
146				if err != nil {
147					t.Fatal(err)
148				}
149				j := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: tc.values})
150				waitStatus(t, s, j.ID, StatusSucceeded)
151				if err := s.Close(); err != nil {
152					t.Fatal(err)
153				}
154	
155				rewriteRecordEffectiveInputs(t, dir, j.ID, tc.eff)
156	
157				s2, err := Open(dir)
158				if err != nil {
159					t.Fatal(err)
160				}
161				defer s2.Close()
162				assertCorrespondenceFailure(t, s2, j.ID, tc.values)
163			})
164		}
165	}
166	
167	// 有依赖时：完整保留原始序列、追加数量恰好等于直接依赖数的记录重开后
168	// 保持成功；借依赖之名替换/截短原始部分、漏掉或多出追加输入的记录失败。
169	func TestReopenDependencyEffectiveInputCorrespondence(t *testing.T) {
170		dir := t.TempDir()
171		s, err := Open(dir)
172		if err != nil {
173			t.Fatal(err)
174		}
175		u1 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "u1", Values: []int64{2, -3}})
176		u2 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "u2", Values: []int64{10}})
177		waitStatus(t, s, u1.ID, StatusSucceeded) // sum=-1
178		waitStatus(t, s, u2.ID, StatusSucceeded) // sum=10
179		down := mustSubmit(t, s, SubmitRequest{
180			Submitter: "a", RequestID: "down", Values: []int64{5},
181			Dependencies: []uint64{u1.ID, u2.ID},
182		})
183		done := waitStatus(t, s, down.ID, StatusSucceeded)
184		if done.Archive.Sum != 14 || done.Archive.SumOfSquares != 126 {
185			t.Fatalf("real result=%d,%d", done.Archive.Sum, done.Archive.SumOfSquares)
186		}
187		if err := s.Close(); err != nil {
188			t.Fatal(err)
189		}
190	
191		// 非法的实际输入：长度不对、原始部分被替换或追加部分缺失/多出。
192		bad := []struct {
193			name string
194			eff  []int64
195		}{
196			{"missing one appended upstream sum", []int64{5, -1}},
197			{"extra unrecorded appended input", []int64{5, -1, 10, 10}},
198			{"original replaced by first upstream sum", []int64{-1, -1, 10}},
199			{"original dropped, only appended sums", []int64{-1, 10}},
200			{"reordered across the boundary", []int64{-1, 5, 10}},
201		}
202		for _, tc := range bad {
203			t.Run(tc.name, func(t *testing.T) {
204				d := t.TempDir()
205				// 每个子用例独立复制一份原始归档再篡改。
206				copyArchive(t, dir, d)
207				rewriteRecordEffectiveInputs(t, d, down.ID, tc.eff)
208				s2, err := Open(d)
209				if err != nil {
210					t.Fatal(err)
211				}
212				defer s2.Close()
213				assertCorrespondenceFailure(t, s2, down.ID, []int64{5})
214			})
215		}
216	
217		// 合法的追加输入：原始序列完整保留、追加数量正确，重开后保持原结果。
218		s3, err := Open(dir)
219		if err != nil {
220			t.Fatal(err)
221		}
222		defer s3.Close()
223		g, err := s3.Get(down.ID)
224		if err != nil {
225			t.Fatal(err)
226		}
227		if g.Status != StatusSucceeded || g.Archive == nil {
228			t.Fatalf("valid dependent archive must survive reopen: %s", g.Status)
229		}
230		if g.Archive.Sum != 14 || g.Archive.SumOfSquares != 126 ||
231			g.Archive.Checksum != done.Archive.Checksum {
232			t.Fatalf("archive changed across reopen: %+v", g.Archive)
233		}
234		if len(g.EffectiveValues) != 3 || g.EffectiveValues[0] != 5 ||
235			g.EffectiveValues[1] != -1 || g.EffectiveValues[2] != 10 {
236			t.Fatalf("effective values=%v, want [5 -1 10]", g.EffectiveValues)
237		}
238	}
239	
240	// copyArchive 把一个归档目录中的记录文件复制到另一个（已存在的）目录。
241	func copyArchive(t *testing.T, src, dst string) {
242		t.Helper()
243		entries, err := os.ReadDir(src)
244		if err != nil {
245			t.Fatal(err)
246		}
247		for _, e := range entries {
248			if e.IsDir() || !strings.HasPrefix(e.Name(), "job-") {
249				continue
250			}
251			in, err := os.ReadFile(filepath.Join(src, e.Name()))
252			if err != nil {
253				t.Fatal(err)
254			}
255			if err := os.WriteFile(filepath.Join(dst, e.Name()), in, 0o600); err != nil {
256				t.Fatal(err)
257			}
258		}
259	}
260	
261	// 旧的单依赖记录（只有 has_dependency/dependency_id，没有有序依赖列表，
262	// 归档中同样没有 dependencies 字段）按同一含义判断：实际输入为原始序列
263	// 加唯一上游的总和时恢复为成功，追加数量不对时失败。
264	func TestReopenLegacySingleDependencyCorrespondence(t *testing.T) {
265		dir := t.TempDir()
266		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
267	
268		// 上游作业 1：[2,-3]，成功，总和 -1。
269		up := &storedJob{
270			id: 1, submitter: "a", requestID: "up",
271			values:          []int64{2, -3},
272			effectiveValues: []int64{2, -3},
273			queuedAt:        base, finishedAt: base.Add(time.Second),
274			status: StatusSucceeded,
275		}
276		up.archive = newArchive(up, []int64{2, -3}, -1, 13, up.finishedAt)
277		writeSyntheticRecord(t, dir, up)
278	
279		// 下游作业 2：旧格式单依赖记录——顶层与归档都不写 dependencies 字段。
280		eff := []int64{5, -1}
281		down := &storedJob{
282			id: 2, submitter: "a", requestID: "down",
283			values:          []int64{5},
284			dependencies:    []uint64{1},
285			effectiveValues: eff,
286			queuedAt:        base.Add(2 * time.Second), finishedAt: base.Add(3 * time.Second),
287			status: StatusSucceeded,
288		}
289		arc := newArchive(down, eff, 4, 26, down.finishedAt) // sum=5-1=4, sq=25+1=26
290		arc.Dependencies = nil                               // 旧归档无此字段
291		r := buildLegacyRecord(t, down, arc, eff)
292		if err := os.WriteFile(filepath.Join(dir, jobFileName(2)), r, 0o600); err != nil {
293			t.Fatal(err)
294		}
295	
296		s, err := Open(dir)
297		if err != nil {
298			t.Fatal(err)
299		}
300		g, err := s.Get(2)
301		if err != nil {
302			t.Fatal(err)
303		}
304		if g.Status != StatusSucceeded || g.Archive == nil {
305			t.Fatalf("legacy single-dependency record must stay succeeded: %s", g.Status)
306		}
307		if g.Archive.Sum != 4 || g.Archive.SumOfSquares != 26 {
308			t.Fatalf("legacy result=%d,%d, want 4,26", g.Archive.Sum, g.Archive.SumOfSquares)
309		}
310		if len(g.Dependencies) != 1 || g.Dependencies[0] != 1 {
311			t.Fatalf("legacy dependencies=%v, want [1]", g.Dependencies)
312		}
313		if err := s.Close(); err != nil {
314			t.Fatal(err)
315		}
316	
317		// 同样的旧格式记录若漏掉唯一追加输入，仍按对应关系失败。
318		dir2 := t.TempDir()
319		writeSyntheticRecord(t, dir2, up)
320		badEff := []int64{5} // 应有两个输入，只有原始序列
321		arc2 := newArchive(down, badEff, 5, 25, down.finishedAt)
322		arc2.Dependencies = nil
323		r2 := buildLegacyRecord(t, down, arc2, badEff)
324		if err := os.WriteFile(filepath.Join(dir2, jobFileName(2)), r2, 0o600); err != nil {
325			t.Fatal(err)
326		}
327		s2, err := Open(dir2)
328		if err != nil {
329			t.Fatal(err)
330		}
331		defer s2.Close()
332		assertCorrespondenceFailure(t, s2, 2, []int64{5})
333	}
334	
335	// buildLegacyRecord 构造旧格式单依赖成功记录：序列化后移除顶层与归档中的
336	// dependencies 字段，只保留 has_dependency/dependency_id。
337	func buildLegacyRecord(t *testing.T, j *storedJob, a *Archive, eff []int64) []byte {
338		t.Helper()
339		r := jobRecord{
340			Version: recordVersion,
341			ID:      j.id, Submitter: j.submitter, RequestID: j.requestID,
342			Seed: j.seed, Values: append([]int64(nil), j.values...),
343			HasDependency: true, DependencyID: 1,
344			// Dependencies 刻意留空（omitempty 后落盘无此字段）。
345			QueuedAt: j.queuedAt, StartedAt: j.startedAt, FinishedAt: j.finishedAt,
346			Status:          StatusSucceeded,
347			EffectiveValues: append([]int64(nil), eff...),
348			Archive:         a,
349		}
350		out, err := json.MarshalIndent(&r, "", "  ")
351		if err != nil {
352			t.Fatal(err)
353		}
354		return out
355	}
356	
357	// 上游的成功记录因输入对应关系错误被改判失败后，仍在排队等待它的下游
358	// 沿用既有依赖失败行为级联失败，不能继续用它的结果计算。
359	func TestReopenMismatchedUpstreamCascadesToQueuedDownstream(t *testing.T) {
360		dir := t.TempDir()
361		s, err := Open(dir)
362		if err != nil {
363			t.Fatal(err)
364		}
365		up := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{2, -3}})
366		waitStatus(t, s, up.ID, StatusSucceeded)
367		if err := s.Close(); err != nil {
368			t.Fatal(err)
369		}
370	
371		rewriteRecordEffectiveInputs(t, dir, up.ID, []int64{-3, 2})
372		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
373		writeSyntheticRecord(t, dir, &storedJob{
374			id: 2, submitter: "a", requestID: "down",
375			values: []int64{5}, dependencies: []uint64{up.ID},
376			queuedAt: base,
377			status:   StatusQueued,
378		})
379	
380		s2, err := Open(dir)
381		if err != nil {
382			t.Fatal(err)
383		}
384		defer s2.Close()
385		g1, _ := s2.Get(up.ID)
386		if g1.Status != StatusFailed {
387			t.Fatalf("mismatched upstream: %s, want failed", g1.Status)
388		}
389		g2 := waitStatus(t, s2, 2, StatusFailed)
390		if g2.BlockerID != up.ID || !strings.Contains(g2.FailureReason, "作业 1") {
391			t.Fatalf("downstream must cascade from upstream failure: blocker=%d reason=%q",
392				g2.BlockerID, g2.FailureReason)
393		}
394		if g2.Archive != nil {
395			t.Fatal("downstream must not produce a success archive")
396		}
397	
398		// 提交、查询入口继续可用；新作业正常处理。
399		next := mustSubmit(t, s2, SubmitRequest{Submitter: "b", Values: []int64{1, 2, 3}})
400		done := waitStatus(t, s2, next.ID, StatusSucceeded)
401		if done.Archive.Sum != 6 || done.Archive.SumOfSquares != 14 {
402			t.Fatalf("new job result=%d,%d", done.Archive.Sum, done.Archive.SumOfSquares)
403		}
404	}
405	
406	// 对应关系错误只把成功改判为失败；记录无法读取、格式非法或版本不受支持时
407	// 仍保留已有的打开失败行为，不静默当作失败作业继续服务。
408	func TestReopenUnreadableRecordsStillFailToOpen(t *testing.T) {
409		t.Run("illegal json", func(t *testing.T) {
410			dir := t.TempDir()
411			if err := os.WriteFile(filepath.Join(dir, jobFileName(7)), []byte("{not json"), 0o600); err != nil {
412				t.Fatal(err)
413			}
414			if _, err := Open(dir); err == nil || !strings.Contains(err.Error(), "损坏") {
415				t.Fatalf("illegal json must fail Open with corruption error, got %v", err)
416			}
417		})
418		t.Run("unsupported version", func(t *testing.T) {
419			dir := t.TempDir()
420			r := jobRecord{Version: "numeric-job-v999", ID: 7, Status: StatusSucceeded}
421			out, err := json.Marshal(&r)
422			if err != nil {
423				t.Fatal(err)
424			}
425			if err := os.WriteFile(filepath.Join(dir, jobFileName(7)), out, 0o600); err != nil {
426				t.Fatal(err)
427			}
428			if _, err := Open(dir); err == nil || !strings.Contains(err.Error(), "版本不受支持") {
429				t.Fatalf("unsupported version must fail Open, got %v", err)
430			}
431		})
432		t.Run("unreadable file", func(t *testing.T) {
433			// root 仍可读 0000 权限文件，无法模拟不可读，跳过。
434			if os.Geteuid() == 0 {
435				t.Skip("running as root")
436			}
437			dir := t.TempDir()
438			p := filepath.Join(dir, jobFileName(7))
439			if err := os.WriteFile(p, []byte("{}"), 0o600); err != nil {
440				t.Fatal(err)
441			}
442			if err := os.Chmod(p, 0o000); err != nil {
443				t.Fatal(err)
444			}
445			if _, err := Open(dir); err == nil {
446				t.Fatal("unreadable record must fail Open")
447			}
448			_ = os.Chmod(p, 0o600) // 便于 TempDir 清理
449		})
450	}
